/* ---------- canvas textures ---------- */
function texEnamel(w=128,h=256){const c=mkCanvas(w,h),x=c.getContext('2d');x.fillStyle='#ecebe2';x.fillRect(0,0,w,h);speckle(x,w,h,w*h/10,[233,232,223],10,0.35,2);for(let i=0;i<5;i++)stain(x,srand()*w,srand()*h,10+srand()*40,'120,100,60',0.1);const g=x.createLinearGradient(0,h*0.65,0,h);g.addColorStop(0,'rgba(80,70,50,0)');g.addColorStop(1,'rgba(80,70,50,0.22)');x.fillStyle=g;x.fillRect(0,0,w,h);for(let i=0;i<3;i++){x.strokeStyle='rgba(90,80,60,0.25)';x.lineWidth=1;x.beginPath();const sx=srand()*w;x.moveTo(sx,h*0.2+srand()*h*0.6);x.lineTo(sx+srand()*20-10,h*0.3+srand()*h*0.6);x.stroke();}return c;}
function texBeige(w=128,h=128,base='#d9d1bd'){const c=mkCanvas(w,h),x=c.getContext('2d');x.fillStyle=base;x.fillRect(0,0,w,h);speckle(x,w,h,w*h/8,[214,206,186],12,0.4,2);for(let i=0;i<4;i++)stain(x,srand()*w,srand()*h,10+srand()*30,'150,130,90',0.18);return c;}
function texNote(lines,o={}){const W=o.w||128,H=o.h||160;const c=mkCanvas(W,H),x=c.getContext('2d');x.fillStyle=o.bg||'#f1eee4';x.fillRect(0,0,W,H);if(o.band){x.fillStyle=o.band;x.fillRect(0,0,W,o.bandH||28);}let y=o.y0||20;for(const L of lines){x.fillStyle=L.c||'#222';x.font=L.f||'bold 12px sans-serif';x.fillText(L.t,L.x===undefined?8:L.x,y);y+=L.h||16;}speckle(x,W,H,260,[205,198,182],30,0.18);stain(x,srand()*W,srand()*H,22,'130,105,60',0.14);if(o.coffee){x.strokeStyle='rgba(110,75,40,0.45)';x.lineWidth=3;x.beginPath();x.arc(W*0.7,H*0.75,16,0,Math.PI*2);x.stroke();}return c;}
function texLabel(w,h,bg,lines,o={}){const c=mkCanvas(w,h),x=c.getContext('2d');x.fillStyle=bg;x.fillRect(0,0,w,h);if(o.stripe){x.fillStyle=o.stripe;x.fillRect(0,h*0.38,w,h*0.24);}for(const L of lines){x.fillStyle=L.c||'#fff';x.font=L.f||'bold 14px sans-serif';x.textAlign='center';x.fillText(L.t,L.x||w/2,L.y);}speckle(x,w,h,w*h/20,[128,128,128],40,0.08);return c;}
function texCRTDesk(){/* never used directly: the CRT draws itself */return mkCanvas(4,4);}
function texDeadLCD(){const c=mkCanvas(256,144),x=c.getContext('2d');x.fillStyle='#050608';x.fillRect(0,0,256,144);for(let i=0;i<22;i++){const px=srand()*256;x.fillStyle=['#f0f','#0ff','#ff0','#fff','#f33','#3f3'][i%6];x.globalAlpha=0.35+srand()*0.5;x.fillRect(px,0,1+srand()*3,144);}x.globalAlpha=1;for(let i=0;i<9;i++){const g=x.createRadialGradient(srand()*256,srand()*144,2,srand()*256,srand()*144,30+srand()*40);g.addColorStop(0,'rgba(0,0,0,0.95)');g.addColorStop(1,'rgba(0,0,0,0)');x.fillStyle=g;x.fillRect(0,0,256,144);}for(let i=0;i<5;i++){x.fillStyle=`rgba(${120+srand()*130|0},${60+srand()*100|0},${200+srand()*55|0},0.5)`;x.beginPath();x.ellipse(srand()*256,srand()*144,10+srand()*30,6+srand()*18,srand()*3,0,Math.PI*2);x.fill();}return c;}
function canvasMat(canvas,o={}){const t=mkTex(canvas,1,1);return new THREE.MeshStandardMaterial(Object.assign({map:t,roughness:0.6},o));}

/* ---------- dents ---------- */
const _dm4=new THREE.Matrix4();const DENT_RC=new THREE.Raycaster();
function makeDentable(mesh,o={}){const g=mesh.geometry;g.userData.p0=g.attributes.position.array.slice();mesh.userData.dent=Object.assign({max:0.03,drawable:null,total:0},o);return mesh;}
function dentMesh(mesh,wp,wdir,force,uv){/* push vertices near the blow inward with a soft falloff; seams move together (position-only weighting), only this mesh is re-lit */const D=mesh.userData.dent;if(!D)return false;mesh.updateMatrixWorld(true);const inv=_dm4.copy(mesh.matrixWorld).invert();const lp=wp.clone().applyMatrix4(inv);const ld=wdir.clone().transformDirection(inv).normalize();
  const r=clamp(0.045+force*0.022,0.045,0.16),depth=clamp(0.003+force*0.0055,0.003,D.max);const g=mesh.geometry,pa=g.attributes.position,A=pa.array,P0=g.userData.p0;let moved=0;const r2=r*r;
  for(let i=0;i<pa.count;i++){const i3=i*3;const dx=A[i3]-lp.x,dy=A[i3+1]-lp.y,dz=A[i3+2]-lp.z;const d2=dx*dx+dy*dy+dz*dz;if(d2>r2)continue;const t=1-d2/r2;const f=t*t*depth;let nx=A[i3]+ld.x*f,ny=A[i3+1]+ld.y*f,nz=A[i3+2]+ld.z*f;const ox=nx-P0[i3],oy=ny-P0[i3+1],oz=nz-P0[i3+2];const ol=Math.hypot(ox,oy,oz);if(ol>D.max){const s=D.max/ol;nx=P0[i3]+ox*s;ny=P0[i3+1]+oy*s;nz=P0[i3+2]+oz*s;}A[i3]=nx;A[i3+1]=ny;A[i3+2]=nz;moved++;}
  if(!moved)return false;pa.needsUpdate=true;g.computeVertexNormals();g.computeBoundingSphere();D.total+=force;
  if(D.drawable&&uv){const d=D.drawable;d.blot(uv.x,uv.y,5+force*4,'45,42,38',0.28);if(force>1.1){const ctx=d.ctx,W=d.canvas.width,H=d.canvas.height;const cx=uv.x*W,cy=(1-uv.y)*H;for(let k=0;k<2+force*2;k++){const px=cx+(Math.random()-0.5)*force*7,py=cy+(Math.random()-0.5)*force*7,rr=0.8+Math.random()*2.2;ctx.fillStyle=Math.random()<0.6?'rgba(150,152,156,0.95)':'rgba(96,70,50,0.8)';ctx.beginPath();ctx.arc(px,py,rr,0,Math.PI*2);ctx.fill();}d.mark(cx-force*8-4,cy-force*8-4,cx+force*8+4,cy+force*8+4);}}
  return true;}
function dentEnt(e,p,dir,force){const meshes=e.dentMeshes;if(!meshes||!meshes.length||force<0.25)return false;const d=dir.clone().normalize();DENT_RC.set(p.clone().addScaledVector(d,-0.14),d);DENT_RC.far=0.34;DENT_RC.firstHitOnly=false;const h=DENT_RC.intersectObjects(meshes,false)[0];if(!h)return false;dentMesh(h.object,h.point,d,force,h.uv);S.dent(h.point,force*0.55);if(force>1.2)sparks(h.point,Math.round(force*2),[1,0.8,0.5]);SHADOW.dirty=true;return true;}

/* ---------- E to use ---------- */
const USE={t:0};
function useOwnerOf(e){return e&&(e.use?e:(e.useOwner&&e.useOwner.use?e.useOwner:null));}
function useTarget(){const h=castRay(2.1,{lcord:true});if(!h||!h.ent)return false;const o=useOwnerOf(h.ent);if(!o)return false;o.use(h);return true;}
function updateUsePrompt(dt){USE.t-=dt;if(USE.t>0)return;USE.t=1/12;const el=HUD.el.use;if(!el||!el.style)return;let txt='';if(locked&&!held&&!grab&&!SEAT.active){const h=castRay(2.1,{lcord:true});if(h&&h.ent&&!(tool===3&&h.ent.kin&&!h.ent.dynamic)){/* hands reticle already says it */const o=useOwnerOf(h.ent);if(o){const lab=typeof o.useLabel==='function'?o.useLabel(h):(o.useLabel||'USE');if(lab)txt='[E] '+lab;}}}if(el.textContent!==txt){el.textContent=txt;el.style.display=txt?'block':'none';}}

/* ---------- kinematic appliance doors (static appliance) → limited physics hinge (knocked loose) ---------- */
const KINDOORS=[];const LIMITED=[];
function kinDoor(door,parent,hinge,axis,openAng,o={}){door.noBatch=true;door.kin={parent,hinge:hinge.clone(),axis:axis.clone().normalize(),ang:0,target:0,open:openAng,p0:door.mesh.position.clone(),q0:door.mesh.quaternion.clone(),speed:o.speed||4.5,onChange:o.onChange||null,physOpen:false};KINDOORS.push(door);
  door.use=()=>toggleKinDoor(door);door.useLabel=()=>(door.dynamic?(door.kin.physOpen?'SHUT ':'SWING ')+(o.name||'DOOR'):(door.kin.target!==0?'CLOSE ':'OPEN ')+(o.name||'DOOR'));return door;}
function toggleKinDoor(d){const k=d.kin;if(!d.alive)return;if(d.dynamic){if(!d.body)return;d.body.wakeUp();const s=(k.physOpen?-1:1)*Math.sign(k.open);d.body.angularVelocity.set(k.axis.x*s*3.2,k.axis.y*s*3.2,k.axis.z*s*3.2);k.physOpen=!k.physOpen;S.thup(toT(d.body.position));return;}k.target=k.target!==0?0:k.open;const p=d.mesh.position;if(k.target===0)setTimeout(()=>S.thup(p,1.1),Math.max(0,Math.abs(k.ang)/k.speed*1000-60));else S.thup(p,0.6);}
function poseKinDoor(d,ang){const k=d.kin;k.ang=ang;const q=new THREE.Quaternion().setFromAxisAngle(k.axis,ang);d.mesh.position.copy(k.p0).sub(k.hinge).applyQuaternion(q).add(k.hinge);d.mesh.quaternion.copy(q).multiply(k.q0);if(d.body){d.body.position.set(d.mesh.position.x,d.mesh.position.y,d.mesh.position.z);d.body.quaternion.set(d.mesh.quaternion.x,d.mesh.quaternion.y,d.mesh.quaternion.z,d.mesh.quaternion.w);d.body.aabbNeedsUpdate=true;}if(k.onChange)k.onChange(Math.abs(ang/k.open));SHADOW.dirty=true;}
function updateKinDoors(dt){for(const d of KINDOORS){const k=d.kin;if(!d.alive)continue;if(d.dynamic){if(k.onChange&&d.body&&k.parent.body){/* report rough openness from the hinge angle */const j=k.joint;if(j&&j.curAng!==undefined)k.onChange(clamp(Math.abs(j.curAng/k.open),0,1));}continue;}if(Math.abs(k.ang-k.target)<1e-4)continue;const step=k.speed*dt;poseKinDoor(d,k.ang+clamp(k.target-k.ang,-step,step));}}
function limitHinge(j,parent,door,axis,lo,hi){/* soft angle stops for a cannon hinge, which has none of its own */j.limit=[lo,hi];j.lp=parent;j.ld=door;const qp=parent.mesh.quaternion.clone(),qd=door.mesh.quaternion.clone();j.refQ=qp.clone().invert().multiply(qd);j.axL=axis.clone().applyQuaternion(qd.clone().invert()).normalize();LIMITED.push(j);return j;}
const _lq1=new THREE.Quaternion(),_lq2=new THREE.Quaternion(),_lq3=new THREE.Quaternion();
function updateHingeLimits(){for(const j of LIMITED){if(!j.intact||!j.constraint)continue;const P=j.lp.body,D=j.ld.body;if(!P||!D)continue;_lq1.set(P.quaternion.x,P.quaternion.y,P.quaternion.z,P.quaternion.w);_lq2.set(D.quaternion.x,D.quaternion.y,D.quaternion.z,D.quaternion.w);_lq3.copy(_lq1).invert().multiply(_lq2);_lq3.premultiply(_lq1.copy(j.refQ).invert());const s=_lq3.x*j.axL.x+_lq3.y*j.axL.y+_lq3.z*j.axL.z;let ang=2*Math.atan2(s,_lq3.w);if(ang>Math.PI)ang-=Math.PI*2;if(ang<-Math.PI)ang+=Math.PI*2;j.curAng=ang;const [lo,hi]=j.limit;if(ang>=lo&&ang<=hi)continue;
    const ax=j.axL.clone().applyQuaternion(_lq2);const wr=(D.angularVelocity.x-P.angularVelocity.x)*ax.x+(D.angularVelocity.y-P.angularVelocity.y)*ax.y+(D.angularVelocity.z-P.angularVelocity.z)*ax.z;const over=ang>hi?ang-hi:ang-lo;let corr=-over*9;if((ang>hi&&wr>0)||(ang<lo&&wr<0))corr-=wr*1.05;D.angularVelocity.x+=ax.x*corr;D.angularVelocity.y+=ax.y*corr;D.angularVelocity.z+=ax.z*corr;}}

/* ---------- live power cords: a chain of light bodies from the appliance to a wall socket ---------- */
const CORDS=[];const cordGeo=new THREE.CylinderGeometry(0.0042,0.0042,1,5,1,true);const cordMat=new THREE.MeshStandardMaterial({color:0x1c1c1e,roughness:0.55});const plugMat=new THREE.MeshStandardMaterial({color:0x222224,roughness:0.5});
function mkCord(o){/* o: owner ent, local (owner-local anchor), socket (world point on the outlet face), sn (outlet normal), len, label, onUnplug */const owner=o.owner;owner.mesh.updateMatrixWorld(true);const A=owner.mesh.localToWorld(o.local.clone());const B=o.socket.clone().addScaledVector(o.sn,0.022);const N=Math.max(5,Math.round(o.len/0.09));const segL=o.len/N;
  const C={born:now,owner,local:o.local.clone(),socket:o.socket.clone(),sn:o.sn.clone(),label:o.label||'power cord',segs:[],cons:[],plugged:true,cut:false,onUnplug:o.onUnplug||null,pullN:o.pullN||55,N,segL};
  const pts=[];const dist=A.distanceTo(B);const sag=Math.max(0,(o.len-dist))*0.45;for(let i=1;i<N;i++){const t=i/N;const p=A.clone().lerp(B,t);p.y-=Math.sin(t*Math.PI)*sag;p.addScaledVector(o.sn,0.012);pts.push(p);}
  for(const p of pts){const b=new CANNON.Body({mass:0,shape:new CANNON.Sphere(0.008)});b.position.set(p.x,p.y,p.z);b.collisionFilterGroup=32;b.collisionFilterMask=1|16;const e=mkEnt({body:b,kind:'cord',mat:'plastic',mass:0.03,hp:2,label:C.label,cord:C,castsShadow:false,damp:0.55,adamp:0.9});makeDynamic(e);b.sleepSpeedLimit=0.12;b.sleepTimeLimit=0.6;/* v9.5: a cord bead's spin means nothing and kept it awake */b.angularFactor.set(0,0,0);C.segs.push(e);}
  const pb=new CANNON.Body({mass:0,shape:new CANNON.Box(new CANNON.Vec3(0.017,0.022,0.012))});pb.position.set(B.x,B.y,B.z);const pq=new THREE.Quaternion().setFromUnitVectors(V3(0,0,1),o.sn);pb.quaternion.set(pq.x,pq.y,pq.z,pq.w);pb.collisionFilterGroup=32;pb.collisionFilterMask=1|16;const pm=new THREE.Group();const pbody=new THREE.Mesh(new THREE.BoxGeometry(0.034,0.044,0.024),plugMat);pm.add(pbody);for(const px of[-0.007,0.007]){const pin=new THREE.Mesh(new THREE.BoxGeometry(0.002,0.008,0.014),M.chrome);pin.position.set(px,0.006,-0.018);pin.rotation.z=px<0?0.5:-0.5;pm.add(pin);}const plug=mkEnt({mesh:pm,body:pb,kind:'cord',mat:'plastic',mass:0.08,hp:3,label:'plug',cord:C,castsShadow:false,damp:0.4,adamp:0.6});makeDynamic(plug);pb.sleepSpeedLimit=0.06;C.plug=plug;
  const add=c=>{world.addConstraint(c);C.cons.push(c);return c;};
  C.headC=add(new CANNON.PointToPointConstraint(owner.body,owner.body.pointToLocalFrame(toC(A)),C.segs[0].body,new CANNON.Vec3(0,0,0),400));
  for(let i=0;i<C.segs.length-1;i++)add(new CANNON.DistanceConstraint(C.segs[i].body,C.segs[i+1].body,segL,400));add(new CANNON.DistanceConstraint(C.segs[C.segs.length-1].body,pb,segL,400));
  const anchor=new CANNON.Body({mass:0});anchor.position.set(B.x,B.y,B.z);anchor.collisionFilterGroup=0;anchor.collisionFilterMask=0;world.addBody(anchor);C.socketBody=anchor;C.socketC=new CANNON.PointToPointConstraint(pb,new CANNON.Vec3(0,0,0),anchor,new CANNON.Vec3(0,0,0),1e4);world.addConstraint(C.socketC);
  const im=new THREE.InstancedMesh(cordGeo,cordMat,N+1);im.frustumCulled=false;im.castShadow=false;im.receiveShadow=true;im.userData.cord=C;hitRoot.add(im);C.im=im;CORDS.push(C);updateCordMesh(C,true);return C;}
const _cm=new THREE.Matrix4(),_ccq=new THREE.Quaternion(),_cv=new THREE.Vector3(),_cy=new THREE.Vector3(0,1,0),_cs=new THREE.Vector3();
function cordPoints(C){const pts=[];if(C.owner.alive&&C.headC){C.owner.mesh.updateMatrixWorld(true);pts.push(C.owner.mesh.localToWorld(C.local.clone()));}else pts.push(toT(C.segs[0].body.position));for(const s of C.segs)pts.push(s.alive?toT(s.body.position):null);pts.push(toT(C.plug.body.position));return pts;}
function updateCordMesh(C,force){let awake=force;if(!awake){for(const s of C.segs){if(s.alive&&s.body.sleepState!==2){awake=true;break;}}if(!awake&&C.plug.body.sleepState!==2)awake=true;if(!awake&&C.owner.dynamic&&C.owner.body&&C.owner.body.sleepState!==2)awake=true;}if(!awake)return;const pts=cordPoints(C);let k=0;
  for(let i=0;i<pts.length-1;i++){const a=pts[i],b=pts[i+1];if(!a||!b||(C.breakAt===i)){_cm.makeScale(0,0,0);C.im.setMatrixAt(k++,_cm);continue;}_cv.subVectors(b,a);const L=_cv.length();if(L<1e-5){_cm.makeScale(0,0,0);C.im.setMatrixAt(k++,_cm);continue;}_ccq.setFromUnitVectors(_cy,_cv.multiplyScalar(1/L));_cs.set(1,L,1);_cm.compose(_cv.copy(a).add(b).multiplyScalar(0.5),_ccq,_cs);C.im.setMatrixAt(k++,_cm);}
  while(k<C.im.count){_cm.makeScale(0,0,0);C.im.setMatrixAt(k++,_cm);}C.im.instanceMatrix.needsUpdate=true;C.im.computeBoundingSphere&&0;}
function cordSegFromHit(C,id){return C.segs[clamp(id-1,0,C.segs.length-1)]||C.plug;}
function unplugCord(C,why){if(!C.plugged)return;C.plugged=false;world.removeConstraint(C.socketC);const p=C.socket.clone();const live=power&&!C.cut;S.zap(p);sparks(p,live?28:6,[0.6,0.8,1]);if(live){sparks(p,14,[1,0.7,0.3]);P.emit(p,{count:8,color:[0.2,0.2,0.2],size:0.04,life:1.4,spread:0.3,grav:-0.3,drag:1.2,kind:1});onSpark(p);if(arcLight){arcLight.position.copy(p);arcLight.intensity=25;arcT=0.18;}}C.plug.body.wakeUp();const v=C.plug.body.velocity;v.x+=C.sn.x*1.2;v.y+=0.4;v.z+=C.sn.z*1.2;HUD.msg(why||'[PLUG TORN OUT OF THE WALL]',1.4);if(C.onUnplug)C.onUnplug();}
function cutCord(C,segE,p){if(C.cut)return;C.cut=true;const i=C.segs.indexOf(segE);const ci=clamp(i,0,C.cons.length-1)+1;const c=C.cons[ci];if(c){world.removeConstraint(c);C.breakAt=ci;}const live=power&&C.plugged;if(live){S.arc(p);sparks(p,40,[0.5,0.7,1]);sparks(p,20,[1,0.6,0.2]);onSpark(p);shakeCam(0.4);tripBreaker();HUD.msg('[LIVE APPLIANCE FLEX CUT - RCD TRIPPED]',2.4);}else{S.snap(p);HUD.msg('[POWER CORD CUT]',1.2);}if(C.onUnplug)C.onUnplug();updateCordMesh(C,true);}
const _eqMax=c=>{let f=0;for(const eq of c.equations){const m=Math.abs(eq.multiplier);if(m>f)f=m;}return f;};
function updateCords(){for(const C of CORDS){if(C.plugged&&now-C.born>2.0){/* sustained pull (not a one-frame solver spike) or the plug dragged out of the socket */const f=C.plug.body.sleepState===2?0:_eqMax(C.socketC);/* a sleeping body reports garbage multipliers */C.over=f>C.pullN?(C.over||0)+1:0;if(C.over>=4||C.plug.body.position.vsub(C.socketBody.position).length()>0.07)unplugCord(C);else cordStretch(C);}if(C.headC&&!C.owner.alive){world.removeConstraint(C.headC);C.headC=null;}cordHandTension(C);updateCordMesh(C,false);}}
/* a hand on the cord: walk it taut toward the wall and the plug pops; taut toward the appliance drags it (if loose) or tears the flex out of its strain relief */
function cordHandTension(C){const H=(typeof held!=='undefined')?held:null;if(!H||!H.ent||H.ent.cord!==C||!H.ent.alive){if(C.barOn){C.barOn=false;HUD.hideBar();}C.tug=0;C.tugO=0;return;}const seg=H.ent,i=C.segs.indexOf(seg);if(i<0)return;const dt=1/60;
  const tgt=camera.getWorldPosition(V3()).addScaledVector(camFwd(),H.dist);let k=0,lbl='';
  if(C.plugged){const reach=(C.N-i)*C.segL+0.04;const d=tgt.distanceTo(toT(C.socketBody.position));const over=d-reach;if(over>0.02){C.tug=(C.tug||0)+dt*(1+over*6);k=C.tug/0.35;lbl='PULL · PLUG';if(Math.random()<0.2)S.groan(C.socket,0.25);if(C.tug>=0.35||over>1.2){C.tug=0;C.barOn=false;HUD.hideBar();unplugCord(C,'[PLUG YANKED OUT OF THE WALL]');return;}}else if(C.tug>0)C.tug=Math.max(0,C.tug-dt*2);}
  if(C.headC&&C.owner.alive){C.owner.mesh.updateMatrixWorld(true);const hp=C.owner.mesh.localToWorld(C.local.clone());const reachO=(i+1)*C.segL+0.04;const over=tgt.distanceTo(hp)-reachO;
    if(over>0.03){if(C.owner.dynamic&&C.owner.body){const dir=tgt.clone().sub(hp).normalize();const F=Math.min(C.owner.mass*14,over*900);C.owner.body.wakeUp();C.owner.body.applyForce(toC(dir.multiplyScalar(F)),toC(hp));}
      else{C.tugO=(C.tugO||0)+dt*(1+over*4);const kk=C.tugO/0.6;if(kk>k){k=kk;lbl='PULL · '+(C.label||'cord').toUpperCase();}if(C.tugO>=0.6){C.tugO=0;world.removeConstraint(C.headC);C.headC=null;const live=cordLive(C);C.cut=true;S.snap(hp);S.click(hp,900);sparks(hp,live?30:6,live?[0.5,0.7,1]:[0.9,0.8,0.6]);if(live){S.arc(hp);onSpark(hp);tripBreaker();HUD.msg('[FLEX TORN OUT OF THE APPLIANCE - RCD TRIPPED]',2.2);}else HUD.msg('[FLEX TORN OUT OF THE STRAIN RELIEF]',1.4);if(C.onUnplug)C.onUnplug();}}}else if(C.tugO>0)C.tugO=Math.max(0,C.tugO-dt*2);}
  if(k>0){HUD.bar(clamp(k,0,1),lbl);C.barOn=true;}else if(C.barOn){C.barOn=false;HUD.hideBar();}}
/* v8.1: carried or thrown past its length the cord comes taut, then the plug pops (or the flex gives at the appliance) */
function cordStretch(C){if(!C.plugged||C.cut||!C.headC||!C.owner.alive||!C.owner.dynamic)return;const dt=1/60;C.owner.mesh.updateMatrixWorld(true);const hp=C.owner.mesh.localToWorld(C.local.clone());const d=hp.distanceTo(C.socket);const L=C.N*C.segL;const H=(typeof held!=='undefined')?held:null;const isHeld=H&&H.ent===C.owner;const gap=isHeld?(H.gap||0):0;
  const taut=d>L*0.9||gap>0.35;if(!taut){C.str=Math.max(0,(C.str||0)-dt*2);if(C.strBar){C.strBar=false;HUD.hideBar();}return;}
  C.str=(C.str||0)+dt*((d>L*0.9?0.5+Math.max(0,d/L-0.9)*6:0)+gap*3.5);if(isHeld){HUD.bar(clamp(C.str,0,1),'CORD TAUT · '+(C.label||'cord').toUpperCase());C.strBar=true;if(Math.random()<dt*3)S.groan(C.socket,0.2);}
  if(C.str<1&&d<L*1.25)return;C.str=0;if(C.strBar){C.strBar=false;HUD.hideBar();}if(Math.random()<(gap>0.8?0.45:0.22)){world.removeConstraint(C.headC);C.headC=null;const live=cordLive(C);C.cut=true;S.snap(hp);S.click(hp,900);sparks(hp,live?30:6,live?[0.5,0.7,1]:[0.9,0.8,0.6]);if(live){S.arc(hp);onSpark(hp);tripBreaker();HUD.msg('[FLEX TORN OUT OF THE '+(C.owner.label||'APPLIANCE').split(' (')[0].toUpperCase()+' - RCD TRIPPED]',2.2);}else HUD.msg('[FLEX TORN OUT OF THE STRAIN RELIEF]',1.4);if(C.onUnplug)C.onUnplug();}
  else unplugCord(C,gap>0.6?'[PLUG YANKED OUT OF THE WALL]':'[PLUG POPPED OUT OF THE WALL]');}
function cordLive(C){return !!C&&C.plugged&&!C.cut&&power;}
