function decorToEnt(m,o={}){/* turn a child mesh into its own falling prop */if(!m.parent)return null;m.updateMatrixWorld(true);const pos=new THREE.Vector3(),q=new THREE.Quaternion(),sc=new THREE.Vector3();m.matrixWorld.decompose(pos,q,sc);m.parent.remove(m);m.position.copy(pos);m.quaternion.copy(q);const s=o.size;const b=new CANNON.Body({mass:0,shape:o.cyl?new CANNON.Cylinder(o.cyl[0],o.cyl[1],o.cyl[2],8):new CANNON.Box(new CANNON.Vec3(s.x/2,s.y/2,s.z/2))});b.position.set(pos.x,pos.y,pos.z);b.quaternion.set(q.x,q.y,q.z,q.w);const e=mkEnt(Object.assign({mesh:m,body:b,kind:'prop',mat:'plastic',mass:0.2,hp:2,wakeable:true},o.ent||{}));makeDynamic(e);return e;}
