const canMat=new THREE.MeshStandardMaterial({map:mkTex(canTexSwill,1,1),roughness:0.3,metalness:0.6});const canTopMat=new THREE.MeshStandardMaterial({color:0xc8cacc,roughness:0.25,metalness:0.9});
