function beerCan(pos,rest,o={}){const g=new THREE.Group();const geo=new THREE.CylinderGeometry(0.033,0.033,0.122,16,8);const body=new THREE.Mesh(geo,[canMat,canTopMat,canTopMat]);body.castShadow=true;g.add(body);makeDentable(body,{max:0.012});g.position.copy(pos);const b=new CANNON.Body({mass:0});b.addShape(new CANNON.Cylinder(0.033,0.033,0.122,10));b.position.copy(toC(pos));const e=mkEnt({mesh:g,body:b,kind:'prop',mat:'metal',mass:0.39,hp:2.2,label:o.label||'can of SWILL',wakeable:true,restsOn:rest,noBatch:true,can:true,dentMeshes:[body]});if(rest)rest.dependents.push(e);e.onHardHit=(p,v)=>{if(v>6&&!e.burst)burstCan(e,p);};e.onHardHitV=4;return e;}
function burstCan(e,p){if(e.burst||!e.alive)return;e.burst=true;e.label='burst can of SWILL';wakeEnt(e);S.canBurst(p||toT(e.body.position));const ld=V3(rnd(-1,1),rnd(-0.3,1),rnd(-1,1)).normalize();SPRAYS.push({e,t:1.4,ld});HUD.msg('[CAN BURST - LAGER EVERYWHERE]',1);}
function updateSprays(dt){for(let i=SPRAYS.length-1;i>=0;i--){const s=SPRAYS[i];s.t-=dt;const e=s.e;if(!e.alive||s.t<=0){SPRAYS.splice(i,1);continue;}const b=e.body;b.wakeUp();const q=new THREE.Quaternion(b.quaternion.x,b.quaternion.y,b.quaternion.z,b.quaternion.w);const d=s.ld.clone().applyQuaternion(q);const p=toT(b.position).addScaledVector(d,0.035);P.emit(p,{count:3,color:[0.86,0.62,0.22],cvar:0.05,size:0.016,life:1,vel:d,speed:4,spread:0.3,grav:9.8,drag:0.2,kind:3});if(Math.random()<0.5)P.emit(p,{count:1,color:[0.97,0.95,0.88],size:0.03,life:0.6,vel:d,speed:1.2,spread:0.3,grav:0.5,drag:2,kind:1});const k=s.t*0.5;b.applyImpulse(new CANNON.Vec3(-d.x*k,-d.y*k,-d.z*k),new CANNON.Vec3(d.x*0.03+0.01,0,d.z*0.03));}}
