function bowl(pos,rest,o={}){const pts=[[0.0,0],[0.045,0.002],[0.07,0.02],[0.08,0.05],[0.078,0.055],[0.066,0.022],[0.04,0.008],[0,0.008]];const m=latheBowl(pts,o.mat||M.china);m.castShadow=true;m.position.copy(pos);const b=new CANNON.Body({mass:0});b.addShape(new CANNON.Cylinder(0.08,0.05,0.055,10),new CANNON.Vec3(0,0.0275,0));b.position.copy(toC(pos));const e=mkEnt({mesh:m,body:b,kind:'prop',mat:'china',mass:0.35,hp:1,label:o.label||'cereal bowl',wakeable:true,restsOn:rest});if(rest)rest.dependents.push(e);return e;}
