    const mustard=new THREE.Mesh(new THREE.CylinderGeometry(0.024,0.026,0.15,12),new THREE.MeshStandardMaterial({color:0xe2b51a,roughness:0.35}));mustard.position.set(innerX+0.04,0.05+0.07,0.12);door.mesh.add(mustard);items.push({m:mustard,cyl:[0.024,0.026,0.15],ent:{label:'mustard',mat:'plastic',mass:0.4}});
