function pcPowered(){return cordLive(PC.cord)&&!PC.dead&&PC.parts.psu&&partAttached(PC.parts.psu)&&!PC.parts.psu.dead&&partAttached(PC.parts.board);}
function crtAlive(){return PC.crt&&PC.crt.alive&&!PC.crtGone;}
function pcToggle(){if(!PC.on){if(!pcPowered()){S.click(PC.tower.mesh.getWorldPosition(V3()));HUD.msg(PC.dead?'[BOARD IS COOKED]':(PC.cord&&PC.cord.plugged?(power?'[NOTHING. PSU?]':'[NO POWER]'):'[PC IS UNPLUGGED]'),1.2);return;}PC.on=true;PC.t=0;PC.state='post';PC.beeped=false;S.click(PC.tower.mesh.getWorldPosition(V3()));if(crtAlive()){S.thup(PC.crt.mesh.getWorldPosition(V3()),1.4);S.tone({f:60,f1:50,dur:0.6,type:'sawtooth',gain:0.12,pos:PC.crt.mesh.getWorldPosition(V3())});}}else{PC.on=false;PC.state='off';crtDraw('off');S.click(PC.tower.mesh.getWorldPosition(V3()));}}
function pcDie(p,why){if(PC.dead)return;PC.dead=true;const was=PC.on;PC.on=false;PC.state='off';if(was){S.tone({f:880,f1:110,dur:0.9,type:'square',gain:0.1});sparks(p,30,[1,0.8,0.4]);S.zap(p);onSpark(p);}if(crtAlive())crtDraw('off');HUD.msg(why||'[MOTHERBOARD FRIED]',1.6);}
function updatePC(dt){if(!PC.tower)return;if(PC.on&&!pcPowered()){PC.on=false;PC.state='off';if(crtAlive())crtDraw('off');}
  const P=PC.parts;const spin=PC.on?dt*40:0;PC.fanA+=spin;for(const f of PC.fans){if(f.parent)f.rotation.z=PC.fanA*(f.userData.dir||1);}for(const l of PC.leds)l.material.emissiveIntensity=PC.on?(l.userData.hdd?(Math.random()<0.15?2:0.1):1.5):0;
  if(PC.on){PC.t+=dt;const twrP=PC.tower.mesh.getWorldPosition(V3());S.drone('pcfan',{noise:0.6,flt:'lowpass',ff:520,tones:[{f:118,type:'triangle',g:0.25}],base:0.035});S.droneGain('pcfan',S.dist(twrP));if(crtAlive()){S.drone('crtwhine',{tones:[{f:15700,type:'sine',g:1}],flt:'highpass',ff:9000,base:0.006});S.droneGain('crtwhine',S.dist(PC.crt.mesh.getWorldPosition(V3())));}else S.droneGain('crtwhine',0);
    if(partAttached(P.hdd)&&Math.random()<dt*3)S.click(twrP,900+Math.random()*700);
    const ram=[P.ram1,P.ram2].some(partAttached);const gpu=partAttached(P.gpu);const hdd=partAttached(P.hdd)&&!P.hdd.dead;
    if(PC.state==='post'&&PC.t>0.6){if(!ram){if(!PC.beeped){PC.beeped=true;for(let i=0;i<3;i++)S.beep(440,0.45,i*0.65,0.12);HUD.msg('[POST: NO MEMORY - LONG BEEPS]',1.6);}if(crtAlive()&&PC.crtState!=='nosignal')crtDraw('nosignal');}else{if(!PC.beeped){PC.beeped=true;S.beep(1000,0.12);}if(crtAlive())crtDraw(gpu?'bios':'nosignal');PC.state=gpu?'bios':'nogpu';}}
    if(PC.state==='bios'&&PC.t>2.6){PC.state=hdd?'desktop':'nodisk';if(crtAlive())crtDraw(hdd?'desktop':'nodisk');if(hdd)S.tone({f:523,dur:0.25,gain:0.08,delay:0.0}),S.tone({f:784,dur:0.4,gain:0.07,delay:0.15});}
    if(PC.state==='desktop'){if(!ram||!gpu||!hdd){PC.state='bsod';if(crtAlive())crtDraw(gpu?'bsod':'nosignal');S.beep(220,0.3);}}
  }else{S.droneGain('pcfan',0);S.droneGain('crtwhine',0);}}
