function wallShelf(asm,w,zc,y,wz,depth,label){const cx=PX-depth/2-0.002;const sh=boxEnt(depth,0.025,wz,V3(cx,y,zc),M.pine,{kind:'furniture',mat:'timber',mass:3,hp:6,label,wakeable:true,cut:0});addPart(asm,sh);for(const dz of[-wz/2+0.08,wz/2-0.08]){const br=new THREE.Mesh(new THREE.BoxGeometry(depth*0.8,0.12,0.012),M.darkMetal);br.position.set(0.02,-0.07,dz);sh.mesh.add(br);}const uc=PZ-zc;const near=w.studU.slice().sort((a,b)=>Math.abs(a-uc)-Math.abs(b-uc));for(const su of near.slice(0,2)){if(Math.abs(su-uc)>wz/2)continue;const seg=w.studs.find(s=>Math.abs(s.cross-su)<0.001&&y>=s.from&&y<=s.to);if(seg){const j=addJoint(asm,sh,seg,'lock',{pos:wallPoint(w,su,y,0.01),strength:2600,pryWork:1.0,label:'shelf bracket screws'});j.onBreak=()=>HUD.msg('[SHELF BRACKET TORN OUT]',1.4);}}return sh;}
